package com.careerpilot.assessment;
import com.careerpilot.config.AssessmentProperties;import com.careerpilot.modules.assessment.entity.AssessmentDifficulty;import com.careerpilot.modules.assessment.generation.*;import org.junit.jupiter.api.Test;import java.time.Duration;import java.util.*;import static org.assertj.core.api.Assertions.*;
class AssessmentGenerationTest{
 private final GeneratedQuestionValidator validator=new GeneratedQuestionValidator();
 @Test void acceptsValidProviderDraftAndNormalizesIt(){var provider=new StubProvider(List.of(question("  What is Java? ","Java",1)));var service=new AssessmentGenerationService(new AssessmentProperties(Duration.ofMinutes(20),50,true),provider,validator);assertThat(service.generateDrafts(new AssessmentGenerationRequest("Backend Developer",AssessmentDifficulty.MEDIUM,1,List.of("Java")))).singleElement().satisfies(q->{assertThat(q.questionText()).isEqualTo("What is Java?");assertThat(q.options()).hasSize(4);});}
 @Test void rejectsMalformedGeminiOutputAndFallsBackCleanly(){var malformed=new GeneratedQuestion("Duplicate",AssessmentDifficulty.EASY,"Java","Explanation",List.of(new GeneratedQuestion.GeneratedOption("A","Same",true),new GeneratedQuestion.GeneratedOption("B","Same",false),new GeneratedQuestion.GeneratedOption("C","Three",false),new GeneratedQuestion.GeneratedOption("D","Four",false)));var service=new AssessmentGenerationService(new AssessmentProperties(Duration.ofMinutes(20),50,true),new StubProvider(List.of(malformed)),validator);assertThat(service.generateDrafts(new AssessmentGenerationRequest("Backend",AssessmentDifficulty.EASY,1,List.of("Java")))).isEmpty();}
 @Test void unavailableOrDisabledAiDoesNotAffectDeterministicAssessments(){var service=new AssessmentGenerationService(new AssessmentProperties(Duration.ofMinutes(20),50,false),new StubProvider(List.of(question("Question","Java",1))),validator);assertThat(service.generateDrafts(new AssessmentGenerationRequest("Backend",AssessmentDifficulty.EASY,1,List.of("Java")))).isEmpty();}
 @Test void validatorRejectsDuplicateQuestionsAndMultipleCorrectAnswers(){var duplicate=question("Same question","Java",1);assertThatThrownBy(()->validator.validate(List.of(duplicate,duplicate),Set.of("Java"),10)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->validator.validate(List.of(question("Bad","Java",2)),Set.of("Java"),10)).isInstanceOf(IllegalArgumentException.class);}
 private GeneratedQuestion question(String text,String skill,int correct){List<GeneratedQuestion.GeneratedOption>options=new ArrayList<>();for(int i=0;i<4;i++)options.add(new GeneratedQuestion.GeneratedOption(String.valueOf((char)('A'+i)),"Option "+i,i<correct));return new GeneratedQuestion(text,AssessmentDifficulty.EASY,skill,"Explanation",options);}
 private record StubProvider(List<GeneratedQuestion>questions)implements AssessmentAiQuestionProvider{public List<GeneratedQuestion>generate(AssessmentGenerationRequest request){return questions;}public String model(){return"test-flash";}}
}
